        [scene('Ось абсцисс',{'A':(-3,0),'B':(2,0)},[(0,1,0)]),scene('Ось ординат',{'C':(0,3),'D':(0,-2)},[(1,0,0)]),scene('Точки на осях и вне осей',{'P':(0,-4),'Q':(3,0),'R':(2,-1)},[(0,1,0),(1,0,0)])],
